 * @param {*} payload - 原始响应体
 * @returns {*} 可序列化的日志对象
 */
const formatPayloadForLog = (payload) => {
    if (payload === undefined) {
        return null
    }

    if (Buffer.isBuffer(payload)) {
        return payload.toString('utf-8')
    }

    if (typeof payload === 'string') {
        const trimmedPayload = payload.trim()
        if (!trimmedPayload) {
            return ''
        }

        try {
