  if (!vendor.inputValues.token) throw new Error("缺少 SessionID/Token");

  const baseUrl = vendor.inputValues.baseUrl;
  const headers = getHeaders();
  const chatID = generateChatID();

  // 构造请求体
  const reqBody: any = {
