  const pureBase64 = extractPureBase64(base64);
  // 实际使用时可能需要调用 uploadFileToQwenOss，这里简化处理
  // 返回一个临时的 blob URL 格式，实际由服务端处理
  return `data:image/png;base64,${pureBase64}`;
